    labels: [['Coat', 'غلاف (کوٹ)', 'پوښ'], ['Outer Membrane', 'بیرونی جھلی', 'بهرنۍ غشا'], ['Cortex', 'کورٹیکس', 'کورټېکس'], ['cell Wall', 'خلوی دیوار', 'حجروي دیوال'], ['Inner Membrane', 'اندرونی جھلی', 'داخلي غشا'], ['Core', 'مرکز (کور)', 'مرکزي برخه']].map(([en, ur, ps]) => ({ en, ur, ps })),
